mapper.select:
SELECT display_id,primary_cancer_id, primary_cancer, gene, variant, gene_variant_id, evidence_cancer_id, evidence_cancer, created_by, created_date from panel_display 


		and gene_variant_id = #{gene_variant_id}


		and primary_cancer_id = #{primary_cancer_id}


		and category = #{category}


order by display_id;

SELECT display_id,primary_cancer_id, primary_cancer, gene, variant, gene_variant_id, evidence_cancer_id, evidence_cancer, created_by, created_date from panel_display 


		and primary_cancer_id = #{primary_cancer_id}


		and category = #{category}

		and gene_variant_id is null

order by display_id;
